class Billing {
  calculate(plan: string, amount: number) {
    if (plan === 'premium') return amount * 0.9;
    if (plan === 'silver') return amount * 0.95;
    if (plan === 'basic') return amount;
    return amount;
  }
}

class InvoiceCalculator {
  calculateTotal(type: string, subtotal: number) {
    if (type === 'standard') return subtotal;
    if (type === 'discount') return subtotal * 0.9;
    if (type === 'promo') return subtotal * 0.8 + 5;
    return subtotal;
  }
}

// Version A
abstract class InvoiceType {
  abstract calculate(invoice: Invoice): number;
}
class StandardInvoice extends InvoiceType {
  calculate(invoice: Invoice) { return invoice.subtotal; }
}
class DiscountInvoice extends InvoiceType {
  calculate(invoice: Invoice) { return invoice.subtotal * 0.9; }
}
class Invoice { constructor(public type: InvoiceType, public subtotal: number) {}
  calculateTotal() { return this.type.calculate(this); }
}

// Version B
class InvoiceOld {
  constructor(public type: string, public subtotal: number) {}
  calculateTotal() {
    if (this.type === 'standard') return this.subtotal;
    if (this.type === 'discount') return this.subtotal * 0.9;
    return this.subtotal;
  }
}
